"""No benchmark instance or experimental seed is generated by these tests."""
import json
import tempfile
import unittest
from pathlib import Path

from src.smoke_orchestrator import Orchestrator, PipelineBlocked, SHADOW, SMOKE, validate_plan


class ScaffoldTests(unittest.TestCase):
    def test_shadow_fails_closed_without_generating(self):
        with tempfile.TemporaryDirectory() as td:
            plan = [{'instance_id': 'shadow-0'}]
            runner = Orchestrator(td, SHADOW, plan, 'a' * 64)
            self.assertEqual(runner.initialize()['phase'], 'PLAN_CREATED')
            with self.assertRaisesRegex(PipelineBlocked, 'FAST evaluator'):
                runner.execute()
            self.assertEqual(runner.read_state()['phase'], 'PLAN_CREATED')

    def test_smoke_and_other_research_execution_blocked(self):
        with tempfile.TemporaryDirectory() as td:
            runner = Orchestrator(td, SMOKE, [{'instance_id': 'x'}], 'a' * 64)
            with self.assertRaises(PipelineBlocked):
                runner.execute()
        for ns in ('GENSPACE-FAIL-01-PILOT', 'GENSPACE-FAIL-01-CONFIRM', 'OTHER'):
            with self.assertRaises(ValueError):
                validate_plan([{'instance_id': 'x'}], ns)

    def test_resume_rejects_changed_plan_and_snapshot(self):
        with tempfile.TemporaryDirectory() as td:
            plan = [{'instance_id': 'x'}]
            Orchestrator(td, SHADOW, plan, 'a' * 64).initialize()
            for other_plan, snap in (([{'instance_id': 'y'}], 'a' * 64), (plan, 'b' * 64)):
                with self.assertRaises(ValueError):
                    Orchestrator(td, SHADOW, other_plan, snap).initialize()
            state = Path(td) / 'state.json'
            data = json.loads(state.read_text(encoding='utf8')); data['phase'] = 'BOGUS'
            state.write_text(json.dumps(data), encoding='utf8')
            with self.assertRaises(ValueError):
                Orchestrator(td, SHADOW, plan, 'a' * 64).read_state()

    def test_duplicate_and_unsafe_ids_rejected(self):
        for plan in ([{'instance_id': 'x'}, {'instance_id': 'x'}], [{'instance_id': '../x'}]):
            with self.assertRaises(ValueError):
                validate_plan(plan, SHADOW)


if __name__ == '__main__':
    unittest.main()
